const CRAB_SCALE = 1.1

// Body and props nest inside `bd` so a prop rides the bob and adds its own motion;
// legs stay outside it and step on their own.
const crab = (x: number, y: number, costume: Costume, dim = false, isWalking = false, scale = CRAB_SCALE): string => {
  const groups = new Map<string, string[]>([['bd', []]])
  const f: Fill = (cx, cy, w, h, c, cls = 'bd') => {
    if (!groups.has(cls)) groups.set(cls, [])
    groups.get(cls)?.push(`<rect x="${cx}" y="${cy}" width="${w}" height="${h}" fill="${c}"/>`)
  }
  const draw = WARDROBE[costume] ?? ((g: Fill) => crabBody(g))
  draw(f, colorOf(costume))
  const group = (cls: string) => `<g class="${cls}">${(groups.get(cls) ?? []).join('')}</g>`
  const props = [...groups.keys()].filter(k => k !== 'bd' && k !== 'la' && k !== 'lb')
  const body = `<g class="bd">${(groups.get('bd') ?? []).join('')}${props.map(group).join('')}</g>`
  return `<g transform="translate(${x},${y}) scale(${scale})" opacity="${dim ? 0.45 : 1}" shape-rendering="crispEdges"><g class="c-${costume}${isWalking ? ' run' : ''}">${body}${group('la')}${group('lb')}</g></g>`
}

const statusMark = (x: number, y: number, status: string, color: string): string => {
  if (status === 'running') return `<circle class="live" cx="${x}" cy="${y}" r="3.5" fill="${color}"/>`
  if (status === 'done') return `<path d="M${x - 5} ${y}l3.5 3.5 6.5-7" fill="none" stroke="#3B9C5F" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>`
  if (status === 'failed') return `<path d="M${x - 4} ${y - 4}l8 8M${x + 4} ${y - 4}l-8 8" stroke="#D0453F" stroke-width="1.8" stroke-linecap="round"/>`
  return `<circle cx="${x}" cy="${y}" r="5" fill="none" stroke="#9a9a96" stroke-width="1.4"/><path d="M${x} ${y - 2.5}v2.8l1.8 1.2" fill="none" stroke="#9a9a96" stroke-width="1.4" stroke-linecap="round"/>`
}

const svg = (W: number, H: number, body: string): string =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${PANE_CSS}${CRAB_CSS}${body}</svg>`

// The pane's own title already says "Agents": the header names the flow, if any.
const headerSvg = (W: number, title: string, t: ReturnType<typeof totals>): string => {
  const s = tr()
  const gap = 6
  const tw = (W - gap * 2) / 3
  const top = title ? 28 : 0
  const tile = (i: number, k: string, v: string) =>
    `<rect class="tile" x="${i * (tw + gap)}" y="${top}" width="${tw}" height="40" rx="8"/>
<text class="s" x="${i * (tw + gap) + 9}" y="${top + 16}" font-family="${FONT}" font-size="11">${k}</text>
<text class="t" x="${i * (tw + gap) + 9}" y="${top + 33}" font-family="${FONT}" font-size="15" font-weight="600" font-variant-numeric="tabular-nums">${v}</text>`
  return svg(
    W,
    headerHeight(title),
    `${title ? `<text class="t" x="0" y="15" font-family="${FONT}" font-size="14" font-weight="600">${xml(fitText(title, 14, W))}</text>` : ''}
${tile(0, s.cost, '≈' + fmtCost(t.cost))}${tile(1, s.tokens, fmtTokens(t.tokens))}${tile(2, s.time, fmtTime(t.time))}`,
  )
}

const headerHeight = (title: string): number => (title ? 72 : 44)

// The task's own progress when the worker reports steps; a finished run is full.
const progressOf = (a: AgentRun): number | null => {
  if (a.status === 'done') return 1
  if (a.stepTotal) return Math.min(1, (a.stepDone ?? 0) / a.stepTotal)
  return null
}

const ctxOf = (a: AgentRun): number => (a.contextMax ? Math.min(100, Math.round((a.contextTokens / a.contextMax) * 100)) : 0)

const agentSvg = (W: number, a: AgentRun, at: number): string => {
  const s = tr()
  const costume = costumeOf(a)
  const color = colorOf(costume)
  const ctx = ctxOf(a)
  const textW = W - 42 - 22
  const meta = [a.effort ? `${modelName(a.model)} · ${a.effort}` : modelName(a.model)]
  if (a.round > 1) meta.push(`${s.round} ${a.round}`)
  if (a.status === 'failed') meta.push(s.failed)
  const barW = textW
  const progress = progressOf(a)
  const stats = `ctx ${ctx}% · ${fmtTokens(a.contextTokens)}  ≈${fmtCost(a.costUsd)}  ${fmtTime(elapsed(a, at))}`
  const steps = a.stepTotal ? `${a.stepDone ?? 0}/${a.stepTotal}${a.stepNote ? ' · ' + a.stepNote : ''}` : ''
  const stepsW = Math.max(0, barW - textWidth(stats, 11) - 12)
  // Without reported steps the bar falls back to the context, drawn grey.
  const fillW = Math.round(barW * (progress ?? ctx / 100))
  return svg(
    W,
    66,
    `${crab(0, 14, costume, false, a.status === 'running')}
<text class="t" x="42" y="18" font-family="${FONT}" font-size="13" font-weight="600">${xml(fitText(a.description || a.type, 13, textW))}</text>
<text x="42" y="34" font-family="${FONT}" font-size="11"><tspan fill="${color}">${xml(bareType(a.type))}</tspan><tspan class="s">  ${xml(meta.join('  ·  '))}</tspan></text>
${steps && stepsW > 30 ? `<text class="t" x="42" y="49" font-family="${FONT}" font-size="11" font-variant-numeric="tabular-nums">${xml(fitText(steps, 11, stepsW))}</text>` : ''}
<text class="s" x="${42 + barW}" y="49" text-anchor="end" font-family="${FONT}" font-size="11" font-variant-numeric="tabular-nums">${stats}</text>
<rect class="k" x="42" y="55" width="${barW}" height="4" rx="2"/><rect${progress === null ? ' class="m"' : ''} x="42" y="55" width="${fillW}" height="4" rx="2"${progress === null ? '' : ` fill="${color}"`}/>
${statusMark(W - 8, 16, a.status, color)}
<line class="ln" x1="0" y1="65.5" x2="${W}" y2="65.5"/>`,
  )
}

const plannedSvg = (W: number, p: Planned): string => {
  const costume = plannedCostume(p)
  const color = colorOf(costume)
  const textW = W - 42 - 22
  const meta = [profileLabel(p)]
  if (p.after.length) meta.push(`${tr().after} ${p.after.join(', ')}`)
  return svg(
    W,
    46,
    `${crab(0, 6, costume, true)}
<text class="s" x="42" y="18" font-family="${FONT}" font-size="13" font-weight="600">${xml(fitText(`${p.n}. ${p.title}`, 13, textW))}</text>
<text x="42" y="34" font-family="${FONT}" font-size="11"><tspan fill="${color}">${xml(p.tier)}</tspan><tspan class="m">  ${xml(meta.filter(Boolean).join('  ·  '))}</tspan></text>
${statusMark(W - 8, 16, 'planned', color)}
<line class="ln" x1="0" y1="45.5" x2="${W}" y2="45.5"/>`,
  )
}

const compactSvg = (W: number, list: AgentRun[], planned: Planned[], t: ReturnType<typeof totals>): string => {
  const icon = (k: Costume, s: string, dim: boolean) => ({ k, c: colorOf(k), s, dim })
  const icons = [
    ...list.filter(a => a.status === 'running').map(a => icon(costumeOf(a), 'running', false)),
    ...list.filter(a => a.status !== 'running').map(a => icon(costumeOf(a), a.status, false)),
    ...planned.map(p => icon(plannedCostume(p), 'planned', true)),
  ]
  const fit = Math.max(1, Math.floor((W - 150) / 36))
  const shown = icons.slice(0, fit)
  const more = icons.length - shown.length
  const body = shown
    .map((ic, i) => crab(i * 36, 0, ic.k, ic.dim, ic.s === 'running') + (ic.s === 'running' ? `<circle class="live" cx="${i * 36 + 32}" cy="4" r="3" fill="${ic.c}"/>` : ''))
    .join('')
  const x = shown.length * 36 + (more ? 4 : 0)
  return svg(
    W,
    32,
    `${body}${more ? `<text class="s" x="${x}" y="21" font-family="${FONT}" font-size="12">+${more}</text>` : ''}
<text class="s" x="${W}" y="21" text-anchor="end" font-family="${FONT}" font-size="12" font-variant-numeric="tabular-nums">≈${fmtCost(t.cost)} · ${fmtTokens(t.tokens)} · ${fmtTime(t.time)}</text>`,
  )
}

// --- terminal drawing: the same rows in text.

const STATUS_GLYPH: Record<string, string> = { running: '●', done: '✓', failed: '✗', planned: '◷' }
// The band's crew row says planned with an open circle; the panel keeps its clock.
const CREW_GLYPH: Record<string, string> = { ...STATUS_GLYPH, planned: '○' }

// Opens the agents pane, or closes it when it is up; true when it ends up open.
async function togglePane($: EngineInterface): Promise<boolean> {
  const isOpen = (await $.ui.panes()).some(p => p.id === PANE)
  if (isOpen) {
    await $.ui.close({ id: PANE })
    return false
  }
  const at = await $.clock.now()
  await update($, now, () => at)
  await $.ui.open({ id: PANE, title: tr().pane })
  return true
}

async function autoOpen($: EngineInterface, key: string): Promise<void> {
  const p = await read($, panel)
  if (p.autoOpenedFor === key) return
  await update($, panel, prev => ({ ...prev, autoOpenedFor: key }))
  void $.ui.open({ id: PANE, title: tr().pane })
}

// This mod's own setting, or 'follow' Agent-Pulse's /config rows (ember / subtle without it).
async function refreshLook($: EngineInterface): Promise<void> {
  let rows: unknown = []
  try {
    rows = await $.config.list()
  } catch {
    // No rows: follow falls back to ember / subtle.
  }
  const next = resolveLook(configured, rows)
  if (next.palette === look.palette && next.level === look.level) return
  look = next
  $.ui.invalidate('ui.render')
}

export const register: Register = (on, options) => {
  configured = options
  look = resolveLook(options, [])
  // A (re)load has seen no flow run yet, so a flow already finished does not sparkle.
  isFlowSeenRunning = false
  sweepKey = 0

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    lang = await detectLang($, options.language)
    await refreshLook($)
    // The fallback for a change of Agent-Pulse's that never reached config.set.
    $.clock.every(15_000, () => void refreshLook($))
    await $.tool.register({
      name: 'progress',
      description:
        "Report a multi-agent plan to the progress bar above the prompt and the agents panel. " +
        'Call it after presenting the plan (title, total, tasks, phase "delegate"), each time a task is accepted (done), ' +
        'when switching phase or re-planning (tasks), and once at the end with finished: true. Fields left out keep their previous value. ' +
        'Optional: without it the bar follows subagent spawns and completions by itself.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short name of the overall task, a few words.' },
          total: { type: 'integer', minimum: 0, description: 'Number of planned worker tasks.' },
          done: { type: 'integer', minimum: 0, description: 'Number of tasks accepted after review.' },
          phase: { type: 'string', enum: [...PHASES] },
          finished: { type: 'boolean', description: 'True once the flow is closed.' },
          tasks: {
            type: 'array',
            description:
              'The planned worker tasks in order, numbered from 1. Each title must equal the Agent tool `description` the task will be delegated with, so the panel can match runs to tasks.',
            items: {
              type: 'object',
              properties: {
                title: { type: 'string', description: 'A few words; reused verbatim as the Agent description.' },
                model: {
                  type: 'string',
                  description: 'What the task will run on: `opus`, `sonnet`, `haiku`, `fable` or a model id. With `effort` it picks the crab\'s costume.',
                },
                effort: { type: 'string', enum: ['low', 'medium', 'high', 'xhigh', 'max'] },
                tier: {
                  type: 'string',
                  enum: ['fable', 'heavy', 'careful', 'medium', 'light'],
                  description: 'A savvy-flow worker tier, for when `model` is left out.',
                },
                after: { type: 'array', items: { type: 'integer' }, description: 'Numbers of the tasks this one waits for.' },
              },
              required: ['title'],
            },
          },
        },
      },
    })
    await $.tool.register({
      name: 'step',
      description:
        'For subagents: report progress on your own task to the agents panel. ' +
        'Right after reading the brief, call it with `total` (your plan in 3-8 steps) and `done: 0`; ' +
        'call it again as each step finishes. Cheap and silent: it only draws a bar.',
      inputSchema: {
        type: 'object',
        properties: {
          done: { type: 'integer', minimum: 0, description: 'Steps finished so far.' },
          total: { type: 'integer', minimum: 1, description: 'Steps planned; may change if the plan changes.' },
          note: { type: 'string', description: 'The step in progress, a few words.' },
        },
        required: ['done'],
      },
    })
    await $.command.register({
      name: 'agents-info',
      description: 'Show or hide the panel of subagents: running, finished and planned, with model, context, cost and time',
    })

    // Ticks the running agents' clocks; quiet when nothing runs.
    $.clock.every(1000, () => {
      void (async () => {
        const list = await read($, agents)
        if (!list.some(a => a.status === 'running')) return
        const at = await $.clock.now()
        await update($, now, () => at)
      })()
    })
    return started
  })

  // Another plugin's /config change that this mod follows: the new value is in the rows once it went through.
  // Literals, so the engine can read the matcher off the source.
  on('config.set', { key: ['agent-pulse.palette', 'agent-pulse.animation'] }, async ($, e, next) => {
    const result = await next(e)
    if (result.deny === undefined) await refreshLook($)
    return result
  })

  on('command.run', { command: 'agents-info' }, async $ => {
    const isOpen = await togglePane($)
    return { text: isOpen ? tr().opened : tr().closed }
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const input = e as unknown as ProgressInput
    const prev = await read($, flow)
    if (isNewFlow(prev, input) && input.title !== undefined) {
      // A new flow starts with a clean list; agents still running stay.
      await update($, agents, list => list.filter(a => a.status === 'running'))
    }
    const next = await update($, flow, p => merge(p, input))
    if (next && input.tasks?.length) await autoOpen($, next.title)
    return { result: `ok: ${label(next ?? blank())}` }
  })

  // A worker's own progress: the call runs in the worker's loop, so agentId names it.
  on('tool.call', { tool: STEP_TOOL }, async ($, e) => {
    const input = e as unknown as { done?: number; total?: number; note?: string }
    const agentId = e.agentId
    if (!agentId) return { result: 'ignored: only subagents report steps' }
    await update($, agents, list =>
      list.map(a => {
        if (a.agentId !== agentId) return a
        const total = Math.max(0, Math.round(input.total ?? a.stepTotal ?? 0))
        const done = Math.max(0, Math.round(input.done ?? a.stepDone ?? 0))
        return { ...a, stepTotal: total, stepDone: total ? Math.min(total, done) : done, stepNote: input.note?.trim() || undefined }
      }),
    )
    return { result: 'ok' }
  })

  // Safety net: worker launches move the faint layer even if the orchestrator forgets to report.
  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const type = String(e.subagent_type ?? '')
    if (!type.startsWith('savvy-')) return next(e)

    await update($, flow, prev => {
      const base = prev && !prev.isFinished ? { ...blank(), ...prev } : blank()
      return { ...base, running: base.running + 1, phase: base.phase === 'plan' ? 'delegate' : base.phase }
    })
    try {
      return await next(e)
    } finally {
      await update($, flow, prev => (prev ? { ...prev, running: Math.max(0, prev.running - 1) } : prev))
    }
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (started.deny !== undefined) return started

    const at = await $.clock.now()
    // Outside a /savvy-flow, every non-savvy agent drives the flow row itself (auto.ts).
    const isSavvy = isSavvyType(e.subagentType)
    const isFreshBatch = !isSavvy && startsBatch(await read($, flow))
    const runId = started.agentId ?? e.tool_use_id
    await update($, agents, list => {
      const round = 1 + list.filter(a => norm(a.description) === norm(e.description) && e.description).length
      const run: AgentRun = {
        id: runId,
        agentId: started.agentId,
        type: e.subagentType,
        description: e.description,
        model: started.model,
        status: 'running',
        startedAt: at,
        contextTokens: 0,
        contextMax: windowOf(started.model),
        tokens: 0,
        costUsd: 0,
        steps: 0,
        round,
      }
      // A new batch starts with a clean list, as a new flow does; agents still running stay.
      const kept = isFreshBatch ? list.filter(a => a.status === 'running') : list
      return [...kept.filter(a => a.id !== run.id), run].slice(-200)
    })
    await update($, now, () => at)
    if (!isSavvy) await update($, flow, prev => onSpawn(prev, runId))
    const f = await read($, flow)
    await autoOpen($, f && !f.isFinished ? openKey(f) : isSavvy ? 'flow' : AUTO_TITLE)
    return started
  })

  // Each model request of a subagent: live context, tokens and cost.
  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    const agentId = e.agentId
    const usage = result.usage
    if (!agentId || !usage) return result

    const model = usage.model || e.model
    await update($, agents, list =>
      list.map(a =>
        a.agentId !== agentId
          ? a
          : {
              ...a,
              model,
              effort: typeof e.effort === 'string' ? e.effort : a.effort,
              status: 'running',
              endedAt: undefined,
              contextTokens:
                (usage.input_tokens || 0) +
                (usage.cache_read_input_tokens || 0) +
                (usage.cache_creation_input_tokens || 0) +
                (usage.output_tokens || 0),
              contextMax: windowOf(model),
              tokens:
                a.tokens +
                (usage.input_tokens || 0) +
                (usage.output_tokens || 0) +
                (usage.cache_read_input_tokens || 0) +
                (usage.cache_creation_input_tokens || 0),
              costUsd: a.costUsd + costOf(model, usage),
              steps: a.steps + 1,
            },
      ),
    )
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId) {
      const at = await $.clock.now()
      const counted = isCounted((await read($, agents)).find(a => a.agentId === agentId))
      await update($, agents, list =>
        list.map(a => {
          if (a.agentId !== agentId) return a
          // A run whose steps went unseen still gets the turn's own sum.
          const fallback = a.steps === 0 && e.usage
          return {
            ...a,
            status: e.reason === 'answer' ? 'done' : 'failed',
            endedAt: at,
            ...(fallback && e.usage
              ? {
                  model: e.usage.model || a.model,
                  tokens:
                    e.usage.input_tokens +
                    e.usage.output_tokens +
                    e.usage.cache_read_input_tokens +
                    e.usage.cache_creation_input_tokens,
                  costUsd: costOf(e.usage.model || a.model, e.usage),
                }
              : {}),
          }
        }),
      )
      await update($, now, () => at)
      // The batch's own agents all finished: a spawn-derived flow closes into the green "Done" row.
      const runs = await read($, agents)
      await update($, flow, prev => onFinish(prev, counted, runs))
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const s = tr()
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const list = await read($, agents)
    const f = await read($, flow)
    const p: Panel = await read($, panel)
    const at = Math.max(await read($, now), ...list.map(a => a.startedAt), 0)

    const running = list.filter(a => a.status === 'running').reverse()
    const finished = list.filter(a => a.status !== 'running').reverse()
    const planned = plannedOf(f, list)
    const t = totals(list, at)
    // The pane's title says "Agents"; inside, only the flow's own name.
    const title = f && !f.isFinished ? f.title : ''

    const toggleCompact = (
      <Button
        key="compact"
        label={p.isCompact ? s.expand : s.collapse}
        plain
        onPress={() => update($, panel, prev => ({ ...prev, isCompact: !prev.isCompact }))}
      />
    )
    const toggleDone = (
      <Button
        key="done"
        label={`${p.isDoneCollapsed ? '▸' : '▾'} ${s.finished} · ${finished.length}`}
        plain
        onPress={() => update($, panel, prev => ({ ...prev, isDoneCollapsed: !prev.isDoneCollapsed }))}
      />
    )
    const isEmpty = list.length === 0 && planned.length === 0
    const summary = `≈${fmtCost(t.cost)}, ${fmtTokens(t.tokens)} ${s.tokensWord}, ${fmtTime(t.time)}`

    if (e.surface === 'desktop' && 'Svg' in ui) {
      const { Svg } = ui
      const W = Math.max(240, Math.min(900, (e.props.bodyColumns || 40) * 8 - 8))
      const section = (key: string, text: string) => (
        <Text key={key} dimColor>
          {text}
        </Text>
      )

      if (p.isCompact) {
        return (
          <Box flexDirection="column" gap={1}>
            <Svg source={compactSvg(W, list, planned, t)} alt={`${list.length} ${s.agentsCount}, ${summary}`} width={W} height={32} />
            {toggleCompact}
          </Box>
        )
      }
      return (
        <Box flexDirection="column">
          <Svg source={headerSvg(W, title, t)} alt={title ? `${title}: ${summary}` : summary} width={W} height={headerHeight(title)} />
          {toggleCompact}
          {isEmpty && <Text dimColor>{s.empty}</Text>}
          {running.length > 0 && section('h-run', `${s.running} · ${running.length}`)}
          {running.map(a => (
            <Svg key={a.id} source={agentSvg(W, a, at)} alt={`${a.description}: ${modelName(a.model)}, ${s.isRunning}`} width={W} height={66} />
          ))}
          {finished.length > 0 && toggleDone}
          {!p.isDoneCollapsed &&
            finished.map(a => (
              <Svg key={a.id} source={agentSvg(W, a, at)} alt={`${a.description}: ${modelName(a.model)}, ${s.isFinished}`} width={W} height={66} />
            ))}
          {planned.length > 0 && section('h-plan', `${s.planned} · ${planned.length}`)}
          {planned.map(pl => (
            <Svg key={`plan-${pl.n}`} source={plannedSvg(W, pl)} alt={`${pl.n}. ${pl.title}: ${s.isPlanned}`} width={W} height={46} />
          ))}
        </Box>
      )
    }

    // Terminal: the same content in text rows, with a crab beside each card (DESIGN.md).
    const cols = Math.max(24, e.props.bodyColumns || 40)
    const barW = Math.max(6, Math.min(20, cols - 34))
    const palette = paletteOf(look.palette)
    const Client = 'Client' in ui ? ui.Client : undefined
    // The crab needs room beside the text; on a narrower pane the old glyph layout stays.
    const hasCrab = Client !== undefined && (e.props.bodyColumns || 40) >= CRAB_MIN_COLS
    // Only the newest running agents walk and spin: a big batch must not start a clock per agent.
    const walking = new Set(running.slice(0, MAX_ANIMATED).map(a => a.id))
    // A crab is always this one Client, a still one included (it starts no clock). Its key names the mode,
    // so an agent that finishes gets a fresh instance instead of a timer left running.
    const crabOf = (id: string, costume: Costume, isRunning: boolean) =>
      Client && (
        <Client
          key={`crab-${id}-${isRunning ? 'run' : 'still'}`}
          module="./crab.tsx"
          props={{ costume, accent: colorOf(costume), running: isRunning, dim: !isRunning, level: look.level }}
          width={6}
          height={2}
        />
      )
    // Theme keys, so done and failed follow the person's theme; running keeps the costume's color.
    const statusColor = (a: AgentRun, color: string) => (a.status === 'failed' ? 'error' : a.status === 'done' ? 'success' : color)
    // The bar shows steps when the worker reports them, else its context fill in grey, amber then red as it fills.
    const runBar = (a: AgentRun, color: string, width: number) => {
      const progress = progressOf(a)
      if (progress !== null) return <Text color={color}>{bar(progress, width)}</Text>
      const ctx = ctxOf(a)
      const heat = ctx >= HEAT_AT[1] ? palette.heat[2] : ctx >= HEAT_AT[0] ? palette.heat[0] : undefined
      return heat ? <Text color={heat}>{bar(ctx / 100, width)}</Text> : <Text dimColor>{bar(ctx / 100, width)}</Text>
    }
    const row = (a: AgentRun) => {
      const costume = costumeOf(a)
      const color = colorOf(costume)
      const model = a.effort ? `${modelName(a.model)} · ${a.effort}` : modelName(a.model)
      // Steps and their free-text note go last: a cut line loses them, not the time and cost.
      const steps = a.stepTotal ? ` · ${a.stepDone ?? 0}/${a.stepTotal}${a.stepNote ? ' ' + a.stepNote : ''}` : ''
      const name = (
        <Box flexDirection="row" gap={1}>
          {!hasCrab && <Text color={color}>▣</Text>}
          <Text bold wrap="truncate-end">
            {a.description || a.type}
          </Text>
          <Text color={statusColor(a, color)}>{STATUS_GLYPH[a.status]}</Text>
        </Box>
      )
      const type = (
        <Text dimColor wrap="truncate-end">
          {hasCrab ? '' : '  '}
          {bareType(a.type)} · {model}
          {a.round > 1 ? ` · ${s.round} ${a.round}` : ''}
        </Text>
      )
      return (
        <Box key={a.id} flexDirection="column">
          {hasCrab ? (
            <Box flexDirection="row" gap={1}>
              {crabOf(a.id, costume, a.status === 'running' && walking.has(a.id))}
              <Box flexDirection="column" flexGrow={1} flexShrink={1}>
                {name}
                {type}
              </Box>
            </Box>
          ) : (
            name
          )}
          {!hasCrab && type}
          <Text wrap="truncate-end">
            {hasCrab ? '' : '  '}
            {runBar(a, color, barW)}
            <Text dimColor>
              {' '}
              {fmtTime(elapsed(a, at))} · ≈{fmtCost(a.costUsd)} · ctx {ctxOf(a)}% · {fmtTokens(a.contextTokens)}
              {steps}
            </Text>
          </Text>
        </Box>
      )
    }
    // Compact: one line per agent, the bar only where it fits. A running agent's glyph is a spinner.
    const lineBarW = cols >= 40 ? Math.min(10, cols - 30) : 0
    const line = (a: AgentRun) => {
      const color = colorOf(costumeOf(a))
      return (
        <Box key={a.id} flexDirection="row" gap={1}>
          {Client && a.status === 'running' && walking.has(a.id) && look.level !== 'off' ? (
            <Client
              key={`spin-${a.id}`}
              module="./pulse.tsx"
              props={{ kind: 'spin', frames: SPIN, ms: SPIN_MS, colors: [color] }}
              width={1}
              height={1}
            />
          ) : (
            <Text color={statusColor(a, color)}>{STATUS_GLYPH[a.status]}</Text>
          )}
          <Box flexGrow={1} flexShrink={1}>
            <Text wrap="truncate-end">{a.description || a.type}</Text>
          </Box>
          {lineBarW > 0 && runBar(a, color, lineBarW)}
          <Text dimColor>
            {fmtTime(elapsed(a, at))} ≈{fmtCost(a.costUsd)}
          </Text>
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" justifyContent="space-between">
          <Text bold wrap="truncate-end">
            {title}
          </Text>
          {toggleCompact}
        </Box>
        <Text dimColor>
          {fmtTime(t.time)} · ≈{fmtCost(t.cost)} · {fmtTokens(t.tokens)} {s.tokensWord}
        </Text>
        {p.isCompact ? (
          <Box flexDirection="column">
            {running.map(line)}
            {finished.length > 0 && toggleDone}
            {!p.isDoneCollapsed && finished.map(line)}
            {planned.map(pl => (
              <Text key={`plan-${pl.n}`} dimColor wrap="truncate-end">
                {STATUS_GLYPH.planned} {pl.n}. {pl.title}
              </Text>
            ))}
          </Box>
        ) : (
          <Box flexDirection="column" marginTop={1}>
            {isEmpty && <Text dimColor>{s.empty}</Text>}
            {running.length > 0 && <Text dimColor>{s.running} · {running.length}</Text>}
            {running.map(row)}
            {finished.length > 0 && toggleDone}
            {!p.isDoneCollapsed && finished.map(row)}
            {planned.length > 0 && <Text dimColor>{s.planned} · {planned.length}</Text>}
            {planned.map(pl => {
              const meta = `${[pl.tier, profileLabel(pl)].filter(Boolean).join(' · ')}${pl.after.length ? ` · ${s.after} ${pl.after.join(', ')}` : ''}`
              // A still, dim crab replaces the leading ▢.
              return hasCrab ? (
                <Box key={`plan-${pl.n}`} flexDirection="row" gap={1}>
                  {crabOf(`plan-${pl.n}`, plannedCostume(pl), false)}
                  <Box flexDirection="column" flexGrow={1} flexShrink={1}>
                    <Text dimColor wrap="truncate-end">
                      {pl.n}. {pl.title}
                    </Text>
                    <Text dimColor wrap="truncate-end">
                      {meta}
                    </Text>
                  </Box>
                </Box>
              ) : (
                <Box key={`plan-${pl.n}`} flexDirection="column">
                  <Text dimColor wrap="truncate-end">
                    <Text color={colorOf(plannedCostume(pl))}>▢</Text> {pl.n}. {pl.title}
                  </Text>
                  <Text dimColor wrap="truncate-end">
                    {'  '}
                    {meta}
                  </Text>
                </Box>
              )
            })}
          </Box>
        )}
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const f = await read($, flow)
    if (f === null || e.props.hasSurvey) return next(e)

    // A render that sees the flow go from running to finished keys the sparkle once; a flow already
    // finished when the module loads (a resume, a reload) never does, and a new flow clears it.
    if (f.isFinished) {
      if (isFlowSeenRunning) {
        isFlowSeenRunning = false
        finishSeq += 1
        sweepKey = finishSeq
      }
    } else {
      isFlowSeenRunning = true
      sweepKey = 0
    }

    // The band is one site for every plugin: what the plugins beneath draw
    // stays, under the bar, so another mod's band is never hidden.
    const below = await next(e)
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const list = await read($, agents)
    const crew = list.length + plannedOf(f, list).length
    const isWorking = list.some(a => a.status === 'running')
    const crewButton = (
      <Button key="subagent-crew" label={`×${crew}`} plain hotkey="a" onPress={() => void togglePane($)} />
    )
    const percent = `${Math.round(ratio(f) * 100)}%`
    const dismiss = (
      <Button
        key="subagent-dismiss"
        label="✕"
        plain
        role="dismiss"
        onPress={() => update($, flow, () => null)}
      />
    )

    // The terminal's table answers `'Svg' in ui` too but draws it empty: the text row is its own.
    if (e.surface !== 'terminal' && 'Svg' in ui) {
      const { Svg } = ui
      // About 8 CSS px per reported column; the rest is the count, the dismiss
      // and their gaps. No floor above the slot: a row wider than it would wrap.
      const width = Math.max(180, Math.min(1600, (e.props.bodyColumns || 100) * 8 - 96))
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" alignItems="center" gap={1}>
            <Svg source={rowSvg(f, width, isWorking)} alt={`${f.title}: ${label(f)}, ${percent}`} width={width} height={H} />
            {crewButton}
            {dismiss}
          </Box>
          {below}
        </Box>
      )
    }

    const cols = e.props.bodyColumns
    const palette = paletteOf(look.palette)
    const Client = 'Client' in ui ? ui.Client : undefined
    const isMoving = look.level !== 'off' && Client !== undefined

    // One glyph per agent in its costume's color, running ones first as in the panel: a spinner while it
    // runs, ✓ and ✗ in the theme's colors, a dim ○ while planned. At most MAX_CREW, then `+n`.
    const crewGlyphs = [
      ...list.filter(a => a.status === 'running').reverse().map(a => ({ id: a.id, kind: 'running' as const, color: colorOf(costumeOf(a)) })),
      ...list.filter(a => a.status !== 'running').reverse().map(a => ({ id: a.id, kind: a.status, color: a.status === 'done' ? 'success' : 'error' })),
      ...plannedOf(f, list).map(p => ({ id: `plan-${p.n}`, kind: 'planned' as const, color: colorOf(plannedCostume(p)) })),
    ]
    const shown = crewGlyphs.slice(0, MAX_CREW)
    const more = crewGlyphs.length - shown.length
    const crewW = shown.length + (more > 0 ? `+${more}`.length : 0)
    const glyphRow = shown.length > 0 && (
      <Box key="subagent-glyphs" flexDirection="row">
        {shown.map(g =>
          g.kind === 'running' && isMoving && Client ? (
            <Client
              key={`spin-${g.id}`}
              module="./pulse.tsx"
              props={{ kind: 'spin', frames: SPIN, ms: SPIN_MS, colors: [g.color] }}
              width={1}
              height={1}
            />
          ) : (
            <Text key={g.id} color={g.color} dimColor={g.kind === 'planned'}>
              {CREW_GLYPH[g.kind]}
            </Text>
          ),
        )}
        {more > 0 && <Text dimColor>{`+${more}`}</Text>}
      </Box>
    )

    const titleW = Math.max(8, Math.min(30, f.title.length + 2, Math.floor(cols / 3)))
    // What follows the bar, measured: label, percent, the crew glyphs, the crew button (`a: ×N`) and ✕,
    // and the row's six gaps of 2. The bar takes what is left.
    const tail = label(f).length + percent.length + crewW + `a: ×${crew}`.length + 1 + 12
    const width = Math.max(6, Math.min(40, cols - titleW - tail))
    const color = f.isFinished ? palette.outcome.ok : palette.phase.agent

    // The bar keeps the eighths glyphs but takes its color per cell: shaded core to glow along its length
    // (positions, so a cell keeps its color as the bar fills), the dim ░ beyond, solid once the flow is done.
    const cells = barCells(ratio(f), width)
    const filled = cells.indexOf('░') === -1 ? cells.length : cells.indexOf('░')
    const cell = (c: string, i: number) =>
      c === '░' ? (
        <Text key={`b${i}`} dimColor>
          {c}
        </Text>
      ) : (
        <Text key={`b${i}`} color={f.isFinished ? palette.outcome.ok : shadeOf(palette, 'agent', i / Math.max(1, width - 1))}>
          {c}
        </Text>
      )
    const isPulsing = !f.isFinished && isMoving && (isWorking || f.running > 0) && filled > 0
    const isSweeping = f.isFinished && sweepKey > 0 && look.level === 'full' && Client !== undefined
    const barEl = (
      <Box key="subagent-bar" flexDirection="row" flexShrink={0}>
        {isSweeping && Client ? (
          <Client
            key={`sweep-${sweepKey}`}
            module="./pulse.tsx"
            props={{ kind: 'sweep', chars: cells, done: cells.map(() => palette.outcome.ok), colors: [...palette.sparkle] }}
            width={width}
            height={1}
          />
        ) : isPulsing && Client ? (
          <>
            {filled > 1 && <Text>{cells.slice(0, filled - 1).map(cell)}</Text>}
            <Client
              key="head"
              module="./pulse.tsx"
              props={{ kind: 'spin', frames: [cells[filled - 1] ?? '█'], ms: SPIN_MS, colors: shimmerOf(palette, 'agent') }}
              width={1}
              height={1}
            />
            {filled < cells.length && <Text>{cells.slice(filled).map((c, i) => cell(c, filled + i))}</Text>}
          </>
        ) : (
          <Text>{cells.map(cell)}</Text>
        )}
      </Box>
    )
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={2}>
          <Box width={titleW} flexShrink={0}>
            <Text color={color}>{f.isFinished ? '✓' : '●'} </Text>
            <Text wrap="truncate-end">{f.title}</Text>
          </Box>
          {barEl}
          <Text bold>{label(f)}</Text>
          <Text dimColor>{percent}</Text>
          {glyphRow}
          {crewButton}
          {dismiss}
        </Box>
        {below}
      </Box>
    )
  })
}

